import type { ReactNode } from 'react';

/** Уровень относительно норм: пренебрежимо мало / в допустимых пределах / выше предела. Определяет цвет карточки. */
export type Level = 'negligible' | 'within' | 'exceeds';

/** Итоговые показатели сценария, как их считает калькулятор. */
export interface RiskTotals {
  /** Дополнительный риск за один год потребления (доля, не проценты): 8,6e-7 = 0,86 случая на 1 млн. */
  riskPerYear: number;
  /** Дополнительный риск за весь период потребления (доля). */
  riskTotal: number;
  /** Оценка относительно уровней НРБ-99/2009 п. 2.3; `null` — уровни не посчитаны. */
  riskAssessment: null | {
    level: Level;
    /** Пренебрежимо малый риск (1e-6 в год). */
    negligible: { value: number };
    /** Уровень, от которого установлены пределы доз населения (5e-5 в год); `loc` — место в документе. */
    limit: { value: number; loc?: string };
  };
}

/** Описание колонки таблицы. */
export interface Column<R = any> {
  /** Заголовок колонки. */
  h: string;
  /** Значение ячейки для строки. */
  f: (row: R) => ReactNode;
  /** Класс ячейки (например `num` — число, выравнивание вправо) или функция от строки. */
  c?: string | ((row: R) => string);
  /** Ячейка содержит готовую разметку: `f` возвращает HTML-строку. */
  html?: boolean;
}
